"""Reusable, owner-supplied leadership and sponsorship acknowledgments."""
from html import escape as esc

def render_summary(data,link):
 url=link('projects/ai4labops/acknowledgments/')
 return f'''<aside class="ack-summary" aria-label="Leadership and acknowledgments"><div><div class="eyebrow">People, partnerships & support</div><h2>Led by researchers.<br>Built with operations.</h2><p>AI for Laboratory Operations is led by <strong>PI Dr. Tirthankar Ghosal</strong>, with <strong>Dr. Sanjay Das</strong> as lead R&D personnel, alongside <strong>Dr. Ethan Seefried</strong> and <strong>Dr. Ran Edgeway</strong> in the Learning Systems group (CSMD, CCSD).</p><p>Developed with ORNL Operations collaborators, 25+ subject-matter experts, and ITSD software colleagues.</p><a class="text-link" href="{url}">Meet our collaborators & explore SAILOR →</a></div><div class="sponsor-note"><span class="label">Sponsor acknowledgment</span><h3>Office of the Laboratory Director</h3><p>Operational Excellence Initiatives</p><p>U.S. Department of Energy (DOE)</p><div class="sailor-note"><strong>SAILOR</strong><p>{esc(data['sailor']['expansion'])}</p><span>Building a broader DOE Community of Practice.</span></div></div></aside>'''

def render_full(data,link):
 panels=''.join(f'<article class="ack-panel"><h3>{title}</h3><p>{esc(data[key])}</p></article>' for title,key in [('Research leadership','leadership'),('ORNL Operations collaborators','operations'),('ITSD software & leadership collaboration','engineering')])
 timeline=''.join(f'<article class="ack-panel"><span class="label">{esc(item["date"])}</span><h3>{esc(item["title"])}</h3><p>{esc(item["body"])}</p></article>' for item in data['symposia'])
 return f'''<div class="ack-full"><div class="section-heading"><div><div class="eyebrow">Acknowledgments</div><h2>{esc(data['title'])}</h2></div></div><p class="ack-intro">{esc(data['overview'])}</p><div class="ack-panels">{panels}</div><div class="sailor-banner"><div class="eyebrow">A broader DOE ecosystem</div><h2>{esc(data['sailor']['name'])}</h2><h3>{esc(data['sailor']['expansion'])}</h3><p>{esc(data['sailor']['body'])}</p><span>{esc(data['sailor']['status'])}</span></div><div class="section-heading"><h2>Scientific exchange & community</h2></div><div class="ack-panels two">{timeline}</div><div class="sponsor-ack"><span class="label">Sponsor acknowledgment</span><h3>{esc(data['sponsors'][0])}</h3><p>{esc(data['sponsors'][1])}</p><p>{esc(data['doe'])}</p></div></div>'''
